// FY2027 SSVI — GOLDEN test against CMS's own published per-hospice files.
//
// The expected values here are NOT recomputed from our constants: every `pointAwarded` / `points` is the flag or
// score CMS published for a real hospice (CMS SSVI zip, CMS-1851-F), and the cut values are parsed here from CMS's
// own scoring-components column headers, which the fixture carries verbatim. The fixture is public aggregate
// hospice data with no CCN, name or PHI, generated by `scripts/data/ssvi/build_ssvi_golden_fixture.py` (see its
// header for the source, the run steps and the row-selection rule that keeps CMS's 0.1 rounding from misleading).
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  SSVI_THRESHOLDS_FY2025_DATA,
  type SsviBinaryMetricKey,
  ssviPointAwarded,
  ssviSpendingPoints,
  ssviThresholdsFor,
} from "../src";
import sample from "./fixtures/ssvi-cms-published-sample.json";

type GoldenYear = (typeof sample)["2025"];
// The fixture covers the binary metrics CMS publishes a value for (metric 1's rule is "none provided", no rate).
type GoldenMetric = keyof GoldenYear["metrics"];
const GOLDEN_METRICS = Object.keys(sample["2025"].metrics) as GoldenMetric[];

/** Rows per side of a cut the fixture must carry (the generator keeps at least this many, or refuses to run). */
const MIN_ROWS_PER_SIDE = 12;

describe("the golden fixture's shape", () => {
  it("covers exactly the seven metrics CMS publishes a value for, so none can silently vanish", () => {
    expect([...GOLDEN_METRICS].sort()).toEqual([
      "metric_02",
      "metric_03",
      "metric_04",
      "metric_05",
      "metric_06",
      "metric_07",
      "metric_08",
    ]);
    expect(Object.keys(sample["2024"].metrics).sort()).toEqual([...GOLDEN_METRICS].sort());
  });
});

/** The cut CMS prints in a scoring-components header: "... (87.5%)", "... (9.9 minutes per day)", "40% or more". */
function cutInHeader(metric: GoldenMetric, header: string): number {
  if (metric === "metric_06") return Number(/\(([\d.]+) minutes/.exec(header)?.[1]);
  return Number(/([\d.]+)%/.exec(header)?.[1]) / 100;
}

/** The "less than or equal to $X" upper bound an octile header prints, in whole cents. */
function octileUpperBoundCents(header: string): number {
  const amounts = header.match(/\$[\d,]+\.\d\d/g) ?? [];
  return Math.round(Number((amounts[amounts.length - 1] ?? "").replace(/[$,]/g, "")) * 100);
}

describe.each([
  ["2025", sample["2025"] satisfies GoldenYear],
  ["2024", sample["2024"] satisfies GoldenYear],
] as const)("SSVI cut table for FY%s claims vs CMS's published scores", (_year, golden) => {
  const table = ssviThresholdsFor(golden.dataFiscalYear);

  it("is the table for that data year, not a stand-in", () => {
    expect(table.dataFiscalYear).toBe(golden.dataFiscalYear);
  });

  it.each(GOLDEN_METRICS)("%s: every published point flag is reproduced", (metric) => {
    const rule = table.metrics[metric];
    const wrong = golden.metrics[metric].filter(
      (row) => ssviPointAwarded(row.value, rule) !== row.pointAwarded,
    );
    expect(wrong).toEqual([]);
  });

  it.each(GOLDEN_METRICS)(
    "%s: rows on BOTH sides of the cut, the nearest within two rounding steps of it",
    (metric) => {
      const rule = table.metrics[metric];
      const step = metric === "metric_06" ? 0.1 : 0.001; // CMS publishes values rounded to 0.1 (of a percent)
      const rows = golden.metrics[metric];
      const concern = rows.filter((r) => r.pointAwarded).map((r) => r.value);
      const calm = rows.filter((r) => !r.pointAwarded).map((r) => r.value);
      expect(concern.length).toBeGreaterThanOrEqual(MIN_ROWS_PER_SIDE);
      expect(calm.length).toBeGreaterThanOrEqual(MIN_ROWS_PER_SIDE);
      const nearestConcern = rule.direction === "gte" ? Math.min(...concern) : Math.max(...concern);
      const nearestCalm = rule.direction === "gte" ? Math.max(...calm) : Math.min(...calm);
      expect(Math.abs(nearestConcern - rule.value)).toBeLessThanOrEqual(2 * step + 1e-9);
      expect(Math.abs(nearestCalm - rule.value)).toBeLessThanOrEqual(2 * step + 1e-9);
    },
  );

  it("metric_09: every published spending score is reproduced, boundaries included", () => {
    const wrong = golden.spending.filter(
      (row) =>
        ssviSpendingPoints(row.totalCents, table.spendingOctileUpperBoundsCents) !== row.points,
    );
    expect(wrong).toEqual([]);
  });

  it("carries the cuts and octile bounds CMS prints in its own column headers", () => {
    for (const metric of GOLDEN_METRICS) {
      expect(table.metrics[metric].value).toBeCloseTo(
        cutInHeader(metric, golden.cutHeaders[metric]),
        6,
      );
    }
    expect(table.spendingOctileUpperBoundsCents).toEqual(
      golden.cutHeaders.spending.slice(0, 7).map(octileUpperBoundCents),
    );
  });
});

// The fixture must have teeth: the cuts this table carried before it was corrected (they matched neither CMS data
// year for metrics 4/5, and were the FY2024 values for 3/6/8) have to FAIL against CMS's FY2025 flags.
describe("the golden fixture rejects the FY2025 cuts this table used to carry", () => {
  const OLD_WRONG_CUTS: ReadonlyArray<readonly [GoldenMetric, number]> = [
    ["metric_03", 0.857],
    ["metric_04", 0.475],
    ["metric_05", 0.332],
    ["metric_06", 9.8],
    ["metric_08", 0.15],
  ];

  it.each(OLD_WRONG_CUTS)("%s at %d", (metric, wrongCut) => {
    const rule = { ...ssviThresholdsFor(2025).metrics[metric], value: wrongCut };
    const mismatches = sample["2025"].metrics[metric].filter(
      (row) => ssviPointAwarded(row.value, rule) !== row.pointAwarded,
    );
    expect(mismatches.length).toBeGreaterThan(0);
  });

  it("metric_09 at the octile bounds this table used to carry", () => {
    const oldBoundsCents = [
      635_284, 2_061_210, 4_291_179, 7_680_105, 13_344_080, 24_612_310, 51_720_440,
    ];
    const mismatches = sample["2025"].spending.filter(
      (row) => ssviSpendingPoints(row.totalCents, oldBoundsCents) !== row.points,
    );
    expect(mismatches.length).toBeGreaterThan(0);
  });
});

// The web panel cannot import this package (it pulls in the DB layer), so it mirrors the cut text. This pins the
// mirror to the table: a cut changed here without the panel fails this test instead of drifting silently.
describe("the web SSVI panel's cut text mirrors the FY2025 table", () => {
  const source = readFileSync(
    join(__dirname, "../../../apps/web/src/modules/30-quality/ssvi-summary.ts"),
    "utf8",
  );

  function webCutText(metric: SsviBinaryMetricKey): string {
    const rule = SSVI_THRESHOLDS_FY2025_DATA.metrics[metric];
    const sign = rule.direction === "gte" ? "≥" : "≤";
    if (metric === "metric_01") return "None provided";
    if (metric === "metric_06") return `${sign} ${rule.value} min`;
    const pct =
      metric === "metric_02" ? `${rule.value * 100}%` : `${(rule.value * 100).toFixed(1)}%`;
    return `${sign} ${pct}`;
  }

  const metrics: SsviBinaryMetricKey[] = ["metric_01", ...GOLDEN_METRICS];

  // Matched by the metric's own `code:` inside the same object literal, so a swap between rows cannot pass.
  it.each(metrics)("%s", (metric) => {
    const entry = new RegExp(`code: "ssvi_${metric}"[^}]*?cut: "([^"]*)"`).exec(source);
    expect(entry?.[1]).toBe(webCutText(metric));
  });
});
